const fs = require('node:fs');
const http = require('node:http');
const https = require('node:https');
const path = require('node:path');

const ROOT = __dirname;
const README_PATH = path.join(ROOT, 'README.md');
const OUTPUT_DIR = path.join(ROOT, 'results');
const OUTPUT_PATH = path.join(OUTPUT_DIR, 'status.json');
const DEFAULT_ENDPOINT = 'http://127.0.0.1:54683/status';
const REQUEST_TIMEOUT_MS = 10000;

function readEndpoint() {
  const readme = fs.readFileSync(README_PATH, 'utf8');
  const urls = readme.match(/https?:\/\/[^\s"'`)\]]+/g) || [];
  const statusUrl = urls.find((u) => u.endsWith('/status')) || urls[0];
  return statusUrl || DEFAULT_ENDPOINT;
}

function request(url) {
  return new Promise((resolve, reject) => {
    const client = url.startsWith('https') ? https : http;
    const req = client.get(url, { timeout: REQUEST_TIMEOUT_MS }, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () =>
        resolve({ statusCode: res.statusCode, body: Buffer.concat(chunks).toString('utf8') })
      );
    });
    req.on('timeout', () => req.destroy(new Error(`Request timed out after ${REQUEST_TIMEOUT_MS}ms: ${url}`)));
    req.on('error', reject);
  });
}

async function main() {
  const endpoint = readEndpoint();
  const res = await request(endpoint);

  if (res.statusCode !== 200) {
    throw new Error(`Unexpected HTTP status ${res.statusCode} from ${endpoint}`);
  }

  let payload;
  try {
    payload = JSON.parse(res.body);
  } catch (err) {
    throw new Error(`Response from ${endpoint} is not valid JSON: ${res.body}`);
  }

  const status = payload && payload.status;
  if (status !== 200) {
    throw new Error(`Expected status=200 in response from ${endpoint}, got ${JSON.stringify(status)}`);
  }

  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  fs.writeFileSync(OUTPUT_PATH, `${JSON.stringify({ status }, null, 2)}\n`);
  console.log(`Wrote status=${status} from ${endpoint} to ${path.relative(ROOT, OUTPUT_PATH)}`);
}

main().catch((err) => {
  console.error(err.message);
  process.exitCode = 1;
});
```

