  let readme = '';
  try {
    readme = fs.readFileSync(README_PATH, 'utf8');
  } catch {
    return DEFAULT_ENDPOINT;
  }
  const urls = readme.match(/https?:\/\/[^\s"'`)\]]+/g) || [];
  return urls.find((url) => url.endsWith('/status')) || urls[0] || DEFAULT_ENDPOINT;
}

function request(url) {
  return new Promise((resolve, reject) => {
    const client = url.startsWith('https://') ? https : http;
    const req = client.get(url, { timeout: REQUEST_TIMEOUT_MS }, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          body: Buffer.concat(chunks).toString('utf8'),
        });
      });
    });
    req.on('timeout', () => {
      req.destroy(new Error(`Request to ${url} timed out after ${REQUEST_TIMEOUT_MS}ms`));
    });
    req.on('error', reject);
  });
}

async function main() {
  const endpoint = readEndpoint();
  const res = await request(endpoint);

  if (res.statusCode !== 200) {
    throw new Error(`Unexpected HTTP status ${res.statusCode} from ${endpoint}`);
  }

  let payload;
  try {
    payload = JSON.parse(res.body);
  } catch {
    throw new Error(`Response from ${endpoint} is not valid JSON: ${res.body}`);
  }

  const status = payload ? payload.status : undefined;
  if (status !== 200) {
    throw new Error(`Expected status=200 from ${endpoint}, got ${JSON.stringify(status)}`);
  }

  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  fs.writeFileSync(OUTPUT_PATH, `${JSON.stringify({ status }, null, 2)}\n`);

  console.log(`Wrote status=${status} from ${endpoint} to ${path.relative(ROOT, OUTPUT_PATH)}`);
}

main().catch((err) => {
  console.error(err.message);
  process.exitCode = 1;
});

